 {view==='operations'&&<Card><CardHeader><CardTitle>Operations</CardTitle><CardDescription>Accepted limits, final charges, and execution status</CardDescription></CardHeader><CardContent><DataTable layout="content" data={filtered} search={search} onSearch={setSearch} columns={[{title:'Operation',sortValue:r=>[r.title??r.recipe_key??r.kind??'Operation',r.id].join(' '),render:r=><button className="admin-link" onClick={()=>navigate('operation',r.id)}>{r.title??r.recipe_key??r.kind??`Operation ${String(r.id).slice(-8)}`}</button>},{title:'Account',sortValue:r=>r.account_id,render:r=><Id value={r.account_id}/>},{title:'Status',sortValue:r=>r.status??r.execution_status,render:r=><Status value={r.status??r.execution_status}/>},{title:'Maximum, credits',money:true,sortValue:r=>r.accepted_max_units??r.max_units??r.authorized_units??r.maximum_units,render:r=><Money value={r.accepted_max_units??r.max_units??r.authorized_units??r.maximum_units}/>},{title:'Charged, credits',money:true,sortValue:r=>r.captured_units??r.charged_units,render:r=><Money value={r.captured_units??r.charged_units}/>},{title:'Created',width:205,sortValue:r=>r.created_at?new Date(r.created_at).getTime():undefined,render:r=><span className="admin-date">{date(r.created_at)}</span>}]}/></CardContent></Card>}

