 {view==='budgets'&&<Card><CardHeader><CardTitle>Execution admission budgets</CardTitle><CardDescription>Limits in USD restrict new attempts without changing customer credits or recorded spend.</CardDescription></CardHeader><CardContent><DataTable data={filtered} search={search} onSearch={setSearch} columns={[{title:'Scope',sortValue:r=>[r.kind,r.budget_key].join(' '),render:r=><>{r.kind==='provider'?(connectionNames[r.budget_key]??'Provider'):'Recipe period'}<Id value={r.budget_key}/></>},{title:'Limit, USD',money:true,sortValue:r=>r.limit_units,render:r=>unitsToUsd(r.limit_units)},{title:'Reserved, USD',money:true,sortValue:r=>r.reserved_units,render:r=>unitsToUsd(r.reserved_units)},{title:'Spent, USD',money:true,sortValue:r=>r.spent_units,render:r=>unitsToUsd(r.spent_units)},{title:'Actions',render:r=><MutationButton size="sm" variant="outline" onClick={()=>budgetForm(r)}>Edit budget</MutationButton>}]} empty="Configure a connection budget or the period budget of a published recipe."/></CardContent></Card>}
